import {
    Component,
    ElementRef,
    EventEmitter,
    Input,
    Output
} from '@angular/core';
import { WalletModel } from 'src/app/_models';

@Component({
    selector: 'app-dropdown-wallet',
    templateUrl: './dropdownWallet.component.html',
    styleUrls: ['./dropdownWallet.component.css']
})
export class DropdownWalletComponent {
    @Input() wallets: WalletModel[] = [];
    @Input() selectedWallet?: WalletModel;
    @Input() readonly: boolean = false;
    @Input() labelString: string = 'Wallet';
    @Input() showLabel: boolean = true;

    @Output() selectWalletEmitter = new EventEmitter<WalletModel>();

    showDropdown = false;
    dropdownNone = true;
    firstLoad = true;
    lastWasTop = false;

    dropDownElement: HTMLElement | null = null;
    buttonDropdownWallet: HTMLElement | null = null;

    constructor(private elRef: ElementRef) {}

    ngOnInit() {
        this.dropDownElement =
            this.elRef.nativeElement.querySelector('#dropdownWallet');
        this.buttonDropdownWallet = this.elRef.nativeElement.querySelector(
            '#buttonDropdownWallet'
        );

        console.log(this.selectedWallet?.id)
    }

    selectWallet(wallet: WalletModel) {
        this.showDropdown = false;
        this.selectedWallet = wallet;
        this.selectWalletEmitter.emit(wallet);
        if (!this.showDropdown) {
            setTimeout(() => {
                this.dropdownNone = true;
            }, 300);
        }
    }

    selectShowDropdown() {
        if (this.readonly || !this.dropDownElement) return;

        if (this.firstLoad || this.showDropdown)
            this.dropDownElement!.style.setProperty(
                'transition',
                'opacity 0.2s ease-in-out'
            );
        else
            this.dropDownElement!.style.setProperty(
                'transition',
                'opacity 0.2s ease-in-out, top 0.2s ease-in-out'
            );

        this.firstLoad = false;
        this.dropDownElement!.style.setProperty('visibility', 'hidden');
        this.dropdownNone = false;

        requestAnimationFrame(() => {
            this.dropDownElement?.style.setProperty(
                '--height',
                this.dropDownElement?.clientHeight + 'px'
            );

            if (
                this.dropDownElement!.clientHeight +
                    this.buttonDropdownWallet!.getBoundingClientRect().top >
                window.innerHeight
            ) {
                if (!this.lastWasTop)
                    this.dropDownElement!.style.setProperty(
                        'transition',
                        'opacity 0.2s ease-in-out'
                    );
                this.dropDownElement?.style.setProperty(
                    '--top',
                    'calc(0px - var(--height) - 20px)'
                );
                this.lastWasTop = true;
            } else {
                if (this.lastWasTop)
                    this.dropDownElement!.style.setProperty(
                        'transition',
                        'opacity 0.2s ease-in-out'
                    );
                this.dropDownElement?.style.setProperty(
                    '--top',
                    'calc(100% + 10px)'
                );
                this.lastWasTop = false;
            }

            this.dropDownElement?.style.setProperty('visibility', 'visible');
        });

        this.showDropdown = !this.showDropdown;
        if (!this.showDropdown) {
            setTimeout(() => {
                this.dropdownNone = true;
            }, 300);
        }
    }
}
<div class="custom-select default-input composed-input d-flex">

    <label *ngIf="showLabel" for="date" class="default-label">{{
        labelString
    }}</label>

    <div
	id="buttonDropdownWallet"
	class="selected-option inner-input" (click)="selectShowDropdown()">
        <span class="w-100Z" *ngIf="!selectedWallet">Select Wallet</span>
        <span class="w-100Z" *ngIf="selectedWallet"> {{ selectedWallet.name }} </span>
    </div>
    <div
		id="dropdownWallet"
        class="default-dropdown"
        [ngClass]="{
            'dropdown-show': showDropdown,
            'dropdown-hide': !showDropdown,
			'dropdown-display-none': firstLoad || dropdownNone,
        }"

    >
	<!-- 'dropdown-display-none': !showDropdown && dropdownNone -->

        <div
            class="default-dropdown-option"
            *ngFor="let wallet of wallets"
            (click)="selectWallet(wallet)"
        >
            <div>
                {{ wallet.name }}
            </div>
            <div class="sub-wallet-container">
                <div class="latest-transaction">21/12/2023 12:51</div>
                <div
                    [ngClass]="{
                        'income-amount': wallet.amount >= 0,
                        'expense-amount': wallet.amount < 0
                    }"
                    class="wallet-amount"
                >
                    {{ wallet.amount }} {{ wallet.currencyCode }}
                </div>
            </div>
        </div>
    </div>
</div>
